UPDATE polymarket_ai_requests
SET prompt_text = #{promptText},
    ai_parameters_json = #{aiParametersJson}
WHERE decision_run_id = #{decisionRunId}

UPDATE polymarket_order_executions
SET execution_status = #{executionStatus},
    skip_reason = #{skipReason},
    order_response = #{orderResponse},
    error = #{error}
WHERE decision_run_id = #{decisionRunId}
